param(
    [string]$ProjectRoot = (Get-Location).Path
)

Set-StrictMode -Version Latest
$ErrorActionPreference = "Stop"

function Project-Path {
    param(
        [Parameter(Mandatory = $true)]
        [string]$RelativePath
    )

    return Join-Path $ProjectRoot $RelativePath
}

function Require-File {
    param(
        [Parameter(Mandatory = $true)]
        [string]$RelativePath
    )

    $fullPath = Project-Path $RelativePath

    if (-not (Test-Path -LiteralPath $fullPath)) {
        throw "Arquivo obrigatorio ausente: $RelativePath"
    }
}

function Write-Base64File {
    param(
        [Parameter(Mandatory = $true)]
        [string]$Path,

        [Parameter(Mandatory = $true)]
        [string]$Base64
    )

    $parent = Split-Path -Parent $Path

    if (
        $parent -and
        -not (Test-Path -LiteralPath $parent)
    ) {
        New-Item `
            -ItemType Directory `
            -Path $parent `
            -Force |
            Out-Null
    }

    $bytes = [Convert]::FromBase64String($Base64)
    [IO.File]::WriteAllBytes($Path, $bytes)
}

function Write-Utf8NoBom {
    param(
        [Parameter(Mandatory = $true)]
        [string]$Path,

        [Parameter(Mandatory = $true)]
        [string]$Content
    )

    $parent = Split-Path -Parent $Path

    if (
        $parent -and
        -not (Test-Path -LiteralPath $parent)
    ) {
        New-Item `
            -ItemType Directory `
            -Path $parent `
            -Force |
            Out-Null
    }

    [IO.File]::WriteAllText(
        $Path,
        $Content,
        [Text.UTF8Encoding]::new($false)
    )
}

Write-Host ""
Write-Host "==========================================================" -ForegroundColor Cyan
Write-Host " HIT MUSIC FINAL - 3 MUDANCAS VITAIS" -ForegroundColor Cyan
Write-Host "==========================================================" -ForegroundColor Cyan
Write-Host "Projeto: $ProjectRoot"
Write-Host ""

Require-File "project.godot"
Require-File "scripts\hit_music_r7\stage.gd"
Require-File "scripts\hit_music_r7\selector.gd"
Require-File "scripts\hit_music_r7\playfield_renderer.gd"
Require-File "scenes\opening.tscn"

$stamp = Get-Date -Format "yyyyMMdd_HHmmss"
$projectParent = Split-Path -Parent $ProjectRoot
$backupRoot = Join-Path `
    $projectParent `
    ("_hit_music_backup_antes_FINAL_" + $stamp)

New-Item `
    -ItemType Directory `
    -Path $backupRoot `
    -Force |
    Out-Null

Write-Host "Criando backup externo..." -ForegroundColor Yellow

$backupItems = @(
    "project.godot",
    "scripts",
    "scenes"
)

foreach ($relativePath in $backupItems) {
    $source = Project-Path $relativePath

    if (-not (Test-Path -LiteralPath $source)) {
        continue
    }

    $destination = Join-Path $backupRoot $relativePath
    $destinationParent = Split-Path -Parent $destination

    New-Item `
        -ItemType Directory `
        -Path $destinationParent `
        -Force |
        Out-Null

    Copy-Item `
        -LiteralPath $source `
        -Destination $destination `
        -Recurse `
        -Force
}

Write-Host ("Backup criado: " + $backupRoot) -ForegroundColor Green
Write-Host ""

$tempRoot = Join-Path `
    $env:TEMP `
    ("hit_music_final_" + $stamp)

New-Item `
    -ItemType Directory `
    -Path $tempRoot `
    -Force |
    Out-Null

$r11Installer = Join-Path $tempRoot "R11BASE.ps1"

Write-Base64File `
    -Path $r11Installer `
    -Base64 ""

Write-Host "1/6 Restaurando e corrigindo a base R11..." -ForegroundColor Yellow

& powershell.exe `
    -NoProfile `
    -ExecutionPolicy Bypass `
    -File $r11Installer `
    -ProjectRoot $ProjectRoot

if ($LASTEXITCODE -ne 0) {
    throw "A instalacao da base R11 terminou com codigo $LASTEXITCODE."
}

Write-Host "2/6 Instalando cliente LED sem perda de comandos..." -ForegroundColor Yellow

Write-Base64File `
    -Path (Project-Path "scripts\hit_music_r7\led_client.gd") `
    -Base64 ""

Write-Host "3/6 Instalando renderer grande, brilhante e geometrico..." -ForegroundColor Yellow

Write-Base64File `
    -Path (Project-Path "scripts\hit_music_r7\playfield_renderer.gd") `
    -Base64 ""

Write-Host "4/6 Instalando LEDs persistentes do menu e gameplay..." -ForegroundColor Yellow

Write-Base64File `
    -Path (Project-Path "scripts\hit_music_r7\stage_final.gd") `
    -Base64 ""

Write-Base64File `
    -Path (Project-Path "scripts\hit_music_r7\selector_final.gd") `
    -Base64 ""

$songWrappers = [ordered]@{
    "scripts\carmine.gd" = "carmine"
    "scripts\dragon_ball.gd" = "dragon_ball"
    "scripts\demon.gd" = "demon"
    "scripts\fairy.gd" = "fairy"
    "scripts\naruto.gd" = "naruto"
    "scripts\rick_morty.gd" = "rick_morty"
    "scripts\soul.gd" = "soul"
}

foreach ($relativePath in $songWrappers.Keys) {
    $songId = $songWrappers[$relativePath]

    $wrapper = (
        'extends "res://scripts/hit_music_r7/stage_final.gd"'
        + "`r`n`r`n"
        + "func _song_id() -> String:`r`n"
        + "`treturn `"$songId`"`r`n"
    )

    Write-Utf8NoBom `
        -Path (Project-Path $relativePath) `
        -Content $wrapper
}

Write-Utf8NoBom `
    -Path (Project-Path "scripts\change_scenes.gd") `
    -Content (
        'extends "res://scripts/hit_music_r7/selector_final.gd"'
        + "`r`n"
    )

Write-Host "5/6 Copiando Arduino R11 e ponte COM5..." -ForegroundColor Yellow

Write-Base64File `
    -Path (Project-Path "ARDUINO11.ino") `
    -Base64 ""

Write-Base64File `
    -Path (Project-Path "BRIDGE.ps1") `
    -Base64 ""

Write-Base64File `
    -Path (Project-Path "ABRIR.ps1") `
    -Base64 ""

# Remove scripts posteriores quebrados para o Godot nao tentar analisa-los.
$laterFiles = @(
    "scripts\hit_music_r7\stage_v12.gd",
    "scripts\hit_music_r7\stage_v13.gd",
    "scripts\hit_music_r7\selector_v12.gd",
    "scripts\hit_music_r7\selector_v13.gd",
    "scripts\hit_music_r7\theme_overlay_v12.gd",
    "scripts\hit_music_r7\theme_overlay_v13.gd",
    "scripts\hit_music_r7\effects_overlay_v13.gd",
    "scripts\hit_music_r7\game_hud_v13.gd",
    "scripts\hit_music_r7\stage_carmine_unificado.gd",
    "scripts\hit_music_r7\selector_led_persistente.gd"
)

foreach ($relativePath in $laterFiles) {
    $fullPath = Project-Path $relativePath

    if (Test-Path -LiteralPath $fullPath) {
        Remove-Item `
            -LiteralPath $fullPath `
            -Force
    }
}

# Impede que backups internos sejam importados pelo Godot.
$internalBackups = Get-ChildItem `
    -LiteralPath $ProjectRoot `
    -Directory `
    -ErrorAction SilentlyContinue |
    Where-Object {
        $_.Name -like "_backup_hit_music_*"
    }

foreach ($directory in $internalBackups) {
    Write-Utf8NoBom `
        -Path (Join-Path $directory.FullName ".gdignore") `
        -Content "# Ignorado pelo Godot.`r`n"
}

Write-Host "6/6 Limpando cache e validando..." -ForegroundColor Yellow

Remove-Item `
    -LiteralPath (Project-Path ".godot\editor") `
    -Recurse `
    -Force `
    -ErrorAction SilentlyContinue

Remove-Item `
    -LiteralPath (
        Project-Path ".godot\global_script_class_cache.cfg"
    ) `
    -Force `
    -ErrorAction SilentlyContinue

$requiredFinal = @(
    "scripts\hit_music_r7\stage_v11.gd",
    "scripts\hit_music_r7\selector_v11.gd",
    "scripts\hit_music_r7\stage_final.gd",
    "scripts\hit_music_r7\selector_final.gd",
    "scripts\hit_music_r7\led_client.gd",
    "scripts\hit_music_r7\playfield_renderer.gd",
    "scripts\change_scenes.gd",
    "scripts\carmine.gd",
    "scripts\dragon_ball.gd",
    "scripts\demon.gd",
    "scripts\fairy.gd",
    "scripts\naruto.gd",
    "scripts\rick_morty.gd",
    "scripts\soul.gd",
    "ARDUINO11.ino",
    "BRIDGE.ps1",
    "ABRIR.ps1"
)

foreach ($relativePath in $requiredFinal) {
    $fullPath = Project-Path $relativePath

    if (-not (Test-Path -LiteralPath $fullPath)) {
        throw "Validacao falhou. Arquivo ausente: $relativePath"
    }

    Write-Host ("[OK] " + $relativePath) -ForegroundColor Green
}

$selectorText = Get-Content `
    -LiteralPath (Project-Path "scripts\hit_music_r7\selector_final.gd") `
    -Raw

if ($selectorText -notmatch "MENU_HEARTBEAT_SECONDS") {
    throw "Heartbeat permanente de D2 e D3 nao foi instalado."
}

$stageText = Get-Content `
    -LiteralPath (Project-Path "scripts\hit_music_r7\stage_final.gd") `
    -Raw

if ($stageText -notmatch "LED_HEARTBEAT_SECONDS") {
    throw "Heartbeat das jogadas TAP/HOLD nao foi instalado."
}

if ($stageText -notmatch "_handle_lane_press") {
    throw "Resposta imediata dos inputs nao foi instalada."
}

$rendererText = Get-Content `
    -LiteralPath (Project-Path "scripts\hit_music_r7\playfield_renderer.gd") `
    -Raw

if ($rendererText -notmatch "HOLD CRISTALINO") {
    throw "Novo efeito geometrico do HOLD nao foi instalado."
}

if ($rendererText -notmatch "Fundo totalmente geometrico") {
    throw "Novo fundo geometrico nao foi instalado."
}

Write-Host ""
Write-Host "==========================================================" -ForegroundColor Green
Write-Host " AS 3 MUDANCAS VITAIS FORAM APLICADAS" -ForegroundColor Green
Write-Host "==========================================================" -ForegroundColor Green
Write-Host ""
Write-Host "1. MENU:" -ForegroundColor Cyan
Write-Host "   D2=A e D3=B permanecem acesos."
Write-Host "   As cores mudam conforme o cenario."
Write-Host ""
Write-Host "2. GAMEPLAY:" -ForegroundColor Cyan
Write-Host "   input_a=D2 ate input_h=D9."
Write-Host "   TAP e HOLD sao reenviados a cada 0,10 s."
Write-Host "   O input fisico gera resposta imediata."
Write-Host ""
Write-Host "3. VISUAL:" -ForegroundColor Cyan
Write-Host "   Efeitos de TAP maiores e mais brilhantes."
Write-Host "   HOLD cristalino com hexagonos e losangos."
Write-Host "   Fundo geometrico inteiro, sem arcos cortados."
Write-Host ""
Write-Host "Nenhum commit final foi criado." -ForegroundColor Yellow
Write-Host ""
Write-Host "Agora grave ARDUINO11.ino no Nano." -ForegroundColor Yellow
Write-Host "Depois execute:" -ForegroundColor Cyan
Write-Host "powershell -NoProfile -ExecutionPolicy Bypass -File .\ABRIR.ps1"
